using UnityEngine;using System.Linq;
public static class MirrorPlane{public static string Main(){var s=Object.FindFirstObjectByType<MotorollerController>();var f=s.GetComponentsInChildren<MeshFilter>().First(f=>f.sharedMesh.name=="LeftMirrorGlass");var v=f.sharedMesh.vertices;var center=f.GetComponent<Renderer>().bounds.center;var n=f.transform.TransformDirection(f.sharedMesh.normals[0]);var m=f.GetComponent<Renderer>().sharedMaterial;return "normal="+n+" planedist="+Vector3.Dot(center-f.transform.TransformPoint(v[0]),n)+" cullForward="+m.GetFloat("_CullModeForward")+" vertex="+v[0]+" tris="+v.Length+" material="+m.name;}}
